/**
 * Opt-in retained-store ingestion campaign for matched NONE and READ_COMMITTED comparisons. It uses the same
 * SimpleValueFactory input distribution, indexes, initial map sizes, and map-growth policy as
 * {@link LmdbLargeTransactionGrowthIT}. Each invocation preserves a fresh store below the caller-provided artifact
 * directory, times every public begin/add/commit including growth pauses, then checks the complete contents before and
 * after reopening the store.
 *
 * <p>
 * Invoke with {@code --it LmdbIngestionComparisonIT#runConfiguredCampaign} and the properties
 * {@code rdf4j.lmdb.ingestionComparison.enabled=true}, {@code rdf4j.lmdb.ingestionComparison.mode=NONE} or
 * {@code READ_COMMITTED}, {@code rdf4j.lmdb.ingestionComparison.rows},
 * {@code rdf4j.lmdb.ingestionComparison.transactions}, {@code rdf4j.lmdb.ingestionComparison.forceSync},
 * {@code rdf4j.lmdb.ingestionComparison.minimumResizes}, {@code rdf4j.lmdb.ingestionComparison.minimumHeapBytes}, and
 * {@code rdf4j.lmdb.ingestionComparison.artifacts}. The row count must divide evenly by the public transaction count.
 * NONE requires one public transaction; READ_COMMITTED can use one or more.
 * </p>
 */
public class LmdbIngestionComparisonIT {

	private static final long INITIAL_MAP_BYTES = 1024L * 1024L;
	private static final int PROGRESS_INTERVAL = 1_000_000;
	private static final String SUBJECT_PREFIX = "urn:lmdb:large-transaction:subject:";
	private static final String VALUE_PREFIX = "dictionary-value-for-large-transaction-";
	private static final String VALUE_SUFFIX = "-payload";
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI[] PREDICATES = {
			VF.createIRI("urn:lmdb:large-transaction:predicate:0"),
			VF.createIRI("urn:lmdb:large-transaction:predicate:1"),
			VF.createIRI("urn:lmdb:large-transaction:predicate:2"),
			VF.createIRI("urn:lmdb:large-transaction:predicate:3")
	};
	private static final Resource[][] CONTEXTS = createContexts();

	public static void main(String[] args) throws Exception {
		new LmdbIngestionComparisonIT().runConfiguredCampaign();
	}

	@Test
	@EnabledIfSystemProperty(named = "rdf4j.lmdb.ingestionComparison.enabled", matches = "true")
	void runConfiguredCampaign() throws Exception {
		String mode = requiredProperty("rdf4j.lmdb.ingestionComparison.mode");
		assertTrue(mode.equals("NONE") || mode.equals("READ_COMMITTED"), "unsupported campaign mode: " + mode);
		int totalRows = intProperty("rdf4j.lmdb.ingestionComparison.rows");
		int transactions = intProperty("rdf4j.lmdb.ingestionComparison.transactions");
		assertTrue(totalRows > 0, "the campaign must contain rows");
		assertTrue(transactions > 0 && totalRows % transactions == 0,
				"rows must divide evenly across public transactions");
		assertTrue(mode.equals("READ_COMMITTED") || transactions == 1, "NONE uses one public transaction");
		int rowsPerTransaction = totalRows / transactions;
		boolean forceSync = Boolean.parseBoolean(requiredProperty("rdf4j.lmdb.ingestionComparison.forceSync"));
		int minimumResizes = intProperty("rdf4j.lmdb.ingestionComparison.minimumResizes");
		long minimumHeapBytes = Long.parseLong(requiredProperty("rdf4j.lmdb.ingestionComparison.minimumHeapBytes"));
		assertTrue(Runtime.getRuntime().maxMemory() >= minimumHeapBytes,
				"actual test-process max heap is below the requested comparison heap: "
						+ Runtime.getRuntime().maxMemory() + " < " + minimumHeapBytes);

		Path artifacts = Path.of(requiredProperty("rdf4j.lmdb.ingestionComparison.artifacts"))
				.toAbsolutePath()
				.normalize();
		Files.createDirectories(artifacts);
		Path storeDirectory = artifacts.resolve("store");
		assertFalse(Files.exists(storeDirectory), "campaign stores are retained and must use a fresh path");
		Path journalPath = artifacts.resolve("journal.log");
		try (CampaignJournal journal = new CampaignJournal(journalPath); HeapSampler heapSampler = new HeapSampler()) {
			runCampaign(mode, totalRows, transactions, rowsPerTransaction, forceSync, minimumResizes,
					minimumHeapBytes, storeDirectory, journal, heapSampler);
			journal.heapUsage(heapSampler.finish());
		}
	}

	private static void runCampaign(String mode, int totalRows, int transactions, int rowsPerTransaction,
			boolean forceSync, int minimumResizes, long minimumHeapBytes, Path storeDirectory,
			CampaignJournal journal, HeapSampler heapSampler) throws Exception {
		LmdbStore store = newStore(storeDirectory, forceSync);
		SailRepository repository = new SailRepository(store);
		Progress progress = new Progress();
		try {
			journal.line("start mode=" + mode + " totalRows=" + totalRows + " publicTransactions=" + transactions
					+ " rowsPerTransaction=" + rowsPerTransaction + " forceSync=" + forceSync
					+ " jdk=" + System.getProperty("java.runtime.version") + " vendor="
					+ System.getProperty("java.vendor") + " maxHeapBytes=" + Runtime.getRuntime().maxMemory()
					+ " minimumHeapBytes=" + minimumHeapBytes + " availableProcessors="
					+ Runtime.getRuntime().availableProcessors()
					+ " input=SimpleValueFactory/default indexes/ordinary adds"
					+ " initialMapBytes=" + INITIAL_MAP_BYTES + " bulkOperationSize="
					+ storeConfig(forceSync).getBulkOperationSize() + " store=" + storeDirectory
					+ " journal=" + journal.path);
			journal.line("config tripleIndexes=" + storeConfig(forceSync).getTripleIndexes()
					+ " tripleTermIndexes=" + storeConfig(forceSync).getTripleTermIndexes()
					+ " forceSync=" + forceSync + " mapGrowthThreshold="
					+ storeConfig(forceSync).getMapGrowthThreshold()
					+ " autoGrow=" + storeConfig(forceSync).getAutoGrow());
			repository.init();
			heapSampler.markStoreInitializedBaseline();
			MapGrowthMetrics.Snapshot before = store.getBackingStore().growthMetricsSnapshot();
			LmdbSailStore.NoneIngestionMetrics noneBefore = store.getBackingStore().noneIngestionMetrics();
			journal.checkpoint("before-load", 0, 0, 0, before, noneBefore);
			assertEquals(0L, Values.packLiteral(VF.createLiteral(valueLabel(0))),
					"the generated strings must use the dictionary, with literal inlining enabled");
			assertEquals(0L, Values.packLiteral(VF.createLiteral(valueLabel(totalRows - 1))));

			long startedNanos = System.nanoTime();
			GcSnapshot gcBeforeIngestion = GcSnapshot.capture();
			long totalLoadNanos = 0;
			long totalPublicCommitNanos = 0;
			long finalPublicCommitNanos = 0;
			try (RepositoryConnection connection = repository.getConnection()) {
				for (int transaction = 0; transaction < transactions; transaction++) {
					int firstRow = transaction * rowsPerTransaction;
					int afterLastRow = firstRow + rowsPerTransaction;
					long loadStartedNanos = System.nanoTime();
					progress.stage = "begin-" + transaction;
					connection.begin(mode.equals("NONE") ? IsolationLevels.NONE : IsolationLevels.READ_COMMITTED);
					assertTrue(connection.isActive(), "the public transaction must be active after begin");
					progress.stage = "load-" + transaction;
					for (int index = firstRow; index < afterLastRow; index++) {
						progress.generated++;
						connection.add(VF.createIRI(SUBJECT_PREFIX + index), PREDICATES[index % PREDICATES.length],
								VF.createLiteral(valueLabel(index)), CONTEXTS[index % CONTEXTS.length][0]);
						progress.accepted++;
						if (progress.accepted % PROGRESS_INTERVAL == 0) {
							journal.checkpoint(progress.stage, progress.generated, progress.accepted,
									progress.validated,
									store.getBackingStore().growthMetricsSnapshot(),
									store.getBackingStore().noneIngestionMetrics());
						}
					}
					assertEquals(afterLastRow, progress.accepted, "accepted row count before public commit");
					if (mode.equals("NONE")) {
						assertTrue(connection.isActive(),
								"the public NONE transaction stays active through native chunks");
					}
					long loadElapsedNanos = System.nanoTime() - loadStartedNanos;
					totalLoadNanos += loadElapsedNanos;
					progress.stage = "commit-" + transaction;
					long commitStartedNanos = System.nanoTime();
					connection.commit();
					long commitElapsedNanos = System.nanoTime() - commitStartedNanos;
					totalPublicCommitNanos += commitElapsedNanos;
					if (transaction == transactions - 1) {
						finalPublicCommitNanos = commitElapsedNanos;
					}
					journal.line("transactionTiming index=" + transaction + " rows=" + rowsPerTransaction
							+ " beginAndAddElapsedNanos=" + loadElapsedNanos
							+ " publicCommitElapsedNanos=" + commitElapsedNanos);
					assertFalse(connection.isActive(), "each public transaction commits before the next begins");
				}
			}
			long elapsedNanos = System.nanoTime() - startedNanos;
			MapGrowthMetrics.Snapshot after = store.getBackingStore().growthMetricsSnapshot();
			LmdbSailStore.NoneIngestionMetrics noneAfter = store.getBackingStore().noneIngestionMetrics();
			GcSnapshot gcAfterIngestion = GcSnapshot.capture();
			progress.stage = "verify-committed";
			journal.line("timing mode=" + mode + " rows=" + totalRows + " transactions=" + transactions
					+ " elapsedNanos=" + elapsedNanos + " elapsedSeconds=" + elapsedNanos / 1_000_000_000.0
					+ " rowsPerSecond=" + totalRows * 1_000_000_000.0 / elapsedNanos
					+ " totalBeginAndAddNanos=" + totalLoadNanos
					+ " totalPublicCommitNanos=" + totalPublicCommitNanos
					+ " finalPublicCommitNanos=" + finalPublicCommitNanos);
			journal.line("gc phase=ingestion collectionCount="
					+ (gcAfterIngestion.collectionCount - gcBeforeIngestion.collectionCount)
					+ " collectionTimeMillis="
					+ (gcAfterIngestion.collectionTimeMillis - gcBeforeIngestion.collectionTimeMillis));
			journal.checkpoint("after-load", progress.generated, progress.accepted, progress.validated, after,
					noneAfter);
			assertEquals(totalRows, progress.accepted, "all rows must be accepted");
			assertGrowth(before, after, minimumResizes);
			if (mode.equals("NONE")) {
				assertTrue(noneAfter.checkpoints() > noneBefore.checkpoints(),
						"NONE must publish at least one paired native checkpoint in this campaign");
			}
			long committedValidationStartedNanos = System.nanoTime();
			assertCompleteContents(repository, totalRows, progress, journal, store);
			journal.line("phase=committed-content-validation elapsedNanos="
					+ (System.nanoTime() - committedValidationStartedNanos) + " rows=" + progress.validated);
		} catch (Exception | Error failure) {
			journal.failure(failure, progress, store);
			throw failure;
		} finally {
			repository.shutDown();
		}

		long valueFileBytes = Files.size(storeDirectory.resolve("values/data.mdb"));
		long tripleFileBytes = Files.size(storeDirectory.resolve("triples/data.mdb"));
		journal.line("logicalStoreBytes values=" + valueFileBytes + " triples=" + tripleFileBytes
				+ " sum=" + (valueFileBytes + tripleFileBytes));

		LmdbStore reopenedStore = newStore(storeDirectory, forceSync);
		SailRepository reopened = new SailRepository(reopenedStore);
		try {
			progress.stage = "reopen";
			long reopenInitStartedNanos = System.nanoTime();
			reopened.init();
			journal.line("phase=reopen-init elapsedNanos=" + (System.nanoTime() - reopenInitStartedNanos));
			progress.stage = "verify-reopened";
			long reopenValidationStartedNanos = System.nanoTime();
			assertCompleteContents(reopened, totalRows, progress, journal, reopenedStore);
			journal.line("phase=reopen-content-validation elapsedNanos="
					+ (System.nanoTime() - reopenValidationStartedNanos) + " rows=" + progress.validated);
			journal.line("success mode=" + mode + " committedRows=" + totalRows + " persistedRows=" + totalRows
					+ " publicTransactions=" + transactions + " forceSync=" + forceSync);
		} catch (Exception | Error failure) {
			journal.failure(failure, progress, reopenedStore);
			throw failure;
		} finally {
			reopened.shutDown();
		}
	}

	private static LmdbStore newStore(Path storeDirectory, boolean forceSync) {
		return new LmdbStore(storeDirectory.toFile(), storeConfig(forceSync));
	}

	private static LmdbStoreConfig storeConfig(boolean forceSync) {
		return new LmdbStoreConfig().setTripleDBSize(INITIAL_MAP_BYTES)
				.setValueDBSize(INITIAL_MAP_BYTES)
				.setForceSync(forceSync);
	}

	private static void assertGrowth(MapGrowthMetrics.Snapshot before, MapGrowthMetrics.Snapshot after,
			int minimumResizes) {
		long tripleResizes = after.tripleStoreResizes() - before.tripleStoreResizes();
		long valueResizes = after.valueStoreResizes() - before.valueStoreResizes();
		assertTrue(tripleResizes >= minimumResizes,
				"actual TripleStore map resizes including final commit: " + tripleResizes + "; required: "
						+ minimumResizes);
		assertTrue(valueResizes >= minimumResizes,
				"actual ValueStore map resizes including final commit: " + valueResizes + "; required: "
						+ minimumResizes);
	}

	private static void assertCompleteContents(SailRepository repository, int totalRows, Progress progress,
			CampaignJournal journal, LmdbStore store) throws IOException {
		BitSet seen = new BitSet(totalRows);
		progress.validated = 0;
		try (RepositoryConnection connection = repository.getConnection();
				RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				String subject = statement.getSubject().stringValue();
				if (!statement.getSubject().isIRI() || !subject.startsWith(SUBJECT_PREFIX)) {
					throw new AssertionError("unexpected subject: " + subject);
				}
				int index = Integer.parseInt(subject.substring(SUBJECT_PREFIX.length()));
				if (index < 0 || index >= totalRows) {
					throw new AssertionError("subject outside generated range: " + subject);
				}
				assertEquals(SUBJECT_PREFIX + index, subject);
				if (seen.get(index)) {
					throw new AssertionError("duplicate subject in public iteration: " + subject);
				}
				seen.set(index);
				assertEquals(PREDICATES[index % PREDICATES.length], statement.getPredicate());
				if (!(statement.getObject() instanceof Literal)) {
					throw new AssertionError("unexpected object for subject: " + subject);
				}
				Literal literal = (Literal) statement.getObject();
				assertEquals(valueLabel(index), literal.getLabel());
				assertEquals(XSD.STRING, literal.getDatatype());
				assertFalse(literal.getLanguage().isPresent());
				assertEquals(CONTEXTS[index % CONTEXTS.length][0], statement.getContext());
				progress.validated++;
				if (progress.validated % PROGRESS_INTERVAL == 0) {
					journal.checkpoint(progress.stage, progress.generated, progress.accepted, progress.validated,
							store.getBackingStore().growthMetricsSnapshot(),
							store.getBackingStore().noneIngestionMetrics());
				}
			}
		}
		assertEquals(totalRows, progress.validated, "public committed cardinality");
		assertEquals(totalRows, seen.cardinality(), "distinct generated subjects");
		assertEquals(totalRows, seen.nextClearBit(0), "the full expected subject range must be present");
	}

	private static String requiredProperty(String name) {
		String value = System.getProperty(name);
		if (value == null || value.isBlank()) {
			throw new IllegalArgumentException("missing required system property: " + name);
		}
		return value;
	}

	private static int intProperty(String name) {
		return Integer.parseInt(requiredProperty(name));
	}

	private static String valueLabel(int index) {
		return VALUE_PREFIX + index + VALUE_SUFFIX;
	}

	private static Resource[][] createContexts() {
		Resource[][] contexts = new Resource[8][1];
		for (int index = 1; index < contexts.length; index++) {
			contexts[index][0] = VF.createIRI("urn:lmdb:large-transaction:context:" + index);
		}
		return contexts;
	}

	private static final class Progress {
		private String stage = "initialize";
		private long generated;
		private long accepted;
		private long validated;
	}

	private static final class CampaignJournal implements AutoCloseable {
		private final Path path;
		private final BufferedWriter writer;

		private CampaignJournal(Path path) throws IOException {
			this.path = path;
			writer = Files.newBufferedWriter(path, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
		}

		private void line(String message) throws IOException {
			String line = Instant.now() + " " + message;
			writer.write(line);
			writer.newLine();
			writer.flush();
			System.out.println(line);
		}

		private void checkpoint(String stage, long generated, long accepted, long validated,
				MapGrowthMetrics.Snapshot growth,
				LmdbSailStore.NoneIngestionMetrics none) throws IOException {
			line("stage=" + stage + " generated=" + generated + " accepted=" + accepted
					+ " validated=" + validated + " tripleResizes=" + growth.tripleStoreResizes()
					+ " valueResizes=" + growth.valueStoreResizes() + " growthEpisodes=" + growth.growthEpisodes()
					+ " growthPhase=" + growth.currentPhase() + " noneCheckpoints=" + none.checkpoints()
					+ " capacityReplays=" + none.capacityReplays() + " peakRetainedBytes=" + none.peakRetainedBytes()
					+ " peakRetainedRows=" + none.peakRetainedRows());
		}

		private void heapUsage(HeapSnapshot snapshot) throws IOException {
			line("heapUsed samplingIntervalMillis=" + HeapSampler.SAMPLE_INTERVAL_MILLIS
					+ " samples=" + snapshot.samples + " usedAfterStoreInitBytes=" + snapshot.usedAfterStoreInitBytes
					+ " usedAtEndBytes=" + snapshot.usedAtEndBytes
					+ " sampledPeakUsedBytes=" + snapshot.sampledPeakUsedBytes
					+ " postSystemGcUsedHeapProxyBytes=" + snapshot.postSystemGcUsedHeapProxyBytes
					+ " postSystemGcIsRetentionProxyOnly=true"
					+ " configuredMaxHeapBytes=" + Runtime.getRuntime().maxMemory());
		}

		private void failure(Throwable failure, Progress progress, LmdbStore store) {
			try {
				line("failure stage=" + progress.stage + " generated=" + progress.generated + " accepted="
						+ progress.accepted + " validated=" + progress.validated + " type="
						+ failure.getClass().getName() + " message=" + failure.getMessage());
				checkpoint("failed-" + progress.stage, progress.generated, progress.accepted, progress.validated,
						store.getBackingStore().growthMetricsSnapshot(),
						store.getBackingStore().noneIngestionMetrics());
			} catch (Exception | Error reportingFailure) {
				failure.addSuppressed(reportingFailure);
			}
		}

		@Override
		public void close() throws IOException {
			writer.close();
		}
	}

	private static final class HeapSampler implements AutoCloseable {
		private static final long SAMPLE_INTERVAL_MILLIS = 25;
		private final AtomicBoolean running = new AtomicBoolean(true);
		private final AtomicLong samples = new AtomicLong();
		private final AtomicLong usedAfterStoreInit = new AtomicLong(-1);
		private final AtomicLong usedAtEnd = new AtomicLong();
		private final AtomicLong sampledPeakUsed = new AtomicLong();
		private final Thread thread;
		private HeapSnapshot result;

		private HeapSampler() {
			sample();
			thread = new Thread(() -> {
				while (running.get()) {
					sample();
					LockSupport.parkNanos(SAMPLE_INTERVAL_MILLIS * 1_000_000L);
				}
			}, "lmdb-ingestion-heap-sampler");
			thread.setDaemon(true);
			thread.start();
		}

		private void sample() {
			MemoryUsage usage = ManagementFactory.getMemoryMXBean().getHeapMemoryUsage();
			Runtime runtime = Runtime.getRuntime();
			long used = Math.max(usage.getUsed(), runtime.totalMemory() - runtime.freeMemory());
			usedAfterStoreInit.compareAndSet(-1, used);
			usedAtEnd.set(used);
			sampledPeakUsed.accumulateAndGet(used, Math::max);
			samples.incrementAndGet();
		}

		private void markStoreInitializedBaseline() {
			long used = currentUsedHeap();
			usedAfterStoreInit.set(used);
			usedAtEnd.set(used);
			sampledPeakUsed.accumulateAndGet(used, Math::max);
		}

		private static long currentUsedHeap() {
			Runtime runtime = Runtime.getRuntime();
			return Math.max(ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed(),
					runtime.totalMemory() - runtime.freeMemory());
		}

		private HeapSnapshot finish() throws InterruptedException {
			if (result != null) {
				return result;
			}
			running.set(false);
			LockSupport.unpark(thread);
			thread.join();
			sample();
			System.gc();
			long postSystemGcUsedHeapProxy = currentUsedHeap();
			result = new HeapSnapshot(usedAfterStoreInit.get(), usedAtEnd.get(), sampledPeakUsed.get(),
					postSystemGcUsedHeapProxy, samples.get());
			return result;
		}

		@Override
		public void close() throws InterruptedException {
			finish();
		}
	}

	private static final class GcSnapshot {
		private final long collectionCount;
		private final long collectionTimeMillis;

		private GcSnapshot(long collectionCount, long collectionTimeMillis) {
			this.collectionCount = collectionCount;
			this.collectionTimeMillis = collectionTimeMillis;
		}

		private static GcSnapshot capture() {
			long count = 0;
			long timeMillis = 0;
			for (GarbageCollectorMXBean collector : ManagementFactory.getGarbageCollectorMXBeans()) {
				if (collector.getCollectionCount() >= 0) {
					count += collector.getCollectionCount();
				}
				if (collector.getCollectionTime() >= 0) {
					timeMillis += collector.getCollectionTime();
				}
			}
			return new GcSnapshot(count, timeMillis);
		}
	}

	private static final class HeapSnapshot {
		private final long usedAfterStoreInitBytes;
		private final long usedAtEndBytes;
		private final long sampledPeakUsedBytes;
		private final long postSystemGcUsedHeapProxyBytes;
		private final long samples;

		private HeapSnapshot(long usedAfterStoreInitBytes, long usedAtEndBytes, long sampledPeakUsedBytes,
				long postSystemGcUsedHeapProxyBytes, long samples) {
			this.usedAfterStoreInitBytes = usedAfterStoreInitBytes;
			this.usedAtEndBytes = usedAtEndBytes;
			this.sampledPeakUsedBytes = sampledPeakUsedBytes;
			this.postSystemGcUsedHeapProxyBytes = postSystemGcUsedHeapProxyBytes;
			this.samples = samples;
		}
	}

}
